import sys

def max_final_element(N, a):
    dp = [[0] * N for _ in range(N)]
    move = [[0] * N for _ in range(N)]

    for length in range(2, N + 1):
        for i in range(N - length + 1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = a[i] + a[j]
                move[i][j] = 1
            else:
                dp[i][j] = max(dp[i + 1][j - 1] + a[i] + a[j], dp[i + 1][j] + a[i], dp[i][j - 1] + a[j])
                if dp[i][j] == dp[i + 1][j - 1] + a[i] + a[j]:
                    move[i][j] = 1
                elif dp[i][j] == dp[i + 1][j] + a[i]:
                    move[i][j] = 2
                else:
                    move[i][j] = 3

    result = dp[0][N - 1]
    operations = []
    i, j = 0, N - 1
    while i < j:
        if move[i][j] == 1:
            operations.append(i + 1)
            i += 1
            j -= 1
        elif move[i][j] == 2:
            operations.append(i + 1)
            i += 1
        else:
            operations.append(j + 1)
            j -= 1

    return result, len(operations), operations

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    a = list(map(int, data[1:]))

    result, num_operations, operations = max_final_element(N, a)

    print(result)
    print(num_operations)
    for op in operations:
        print(op)

if __name__ == "__main__":
    main()
